/// <summary>
/// Invoice lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METSalesOrderLoadPlanningAidLinesTmp))]
public METSalesOrderLoadPlanningAidLinesTmp getLines()
{
    select salesOrderLoadPlanningAidLinesTmp;
    return salesOrderLoadPlanningAidLinesTmp;
}

/// <summary> /// Parses the report parameters and fills the <c>salesOrderLoadPlanningAidLinesTmp</c> tables with data. /// </summary> public void processReport() { METSalesOrderLoadPlanningAidLinesTmp metSalesLoadPlanningAidLinesTmp;
contract = this.parmDataContract() as METSalesLoadPlanningContract; createdTransactionId = contract.parmTransaction();
salesOrderLoadPlanningAidLinesTmp.setConnection(this.parmUserConnection());
insert_recordset salesOrderLoadPlanningAidLinesTmp (CompanyName, Warehouse, ReportGeneratedDateTime, Route, ConfirmedShipDate, StopNumber, SalesId, LineNum, Cases, Eaches, Weight, Volume, Pallets, OrderCreatedDateTime, OrderType, OrderSplitGroup, CustAccount, CustomerName) select CompanyName, Warehouse, ReportGeneratedDateTime, Route, ConfirmedShipDate, StopNumber, SalesId, LineNum, Cases, Eaches, Weight, Volume, Pallets, OrderCreatedDateTime, OrderType, OrderSplitGroup, CustAccount, CustomerName from metSalesLoadPlanningAidLinesTmp where metSalesLoadPlanningAidLinesTmp.CreatedTransactionId == createdTransactionId;
delete_from metSalesLoadPlanningAidLinesTmp where metSalesLoadPlanningAidLinesTmp.CreatedTransactionId == createdTransactionId; }

